// Reuse exactly the self-hosted next/font faces generated by this docs build.
import { readdir, readFile, writeFile, access } from 'node:fs/promises';
import path from 'node:path';
const project=path.resolve(import.meta.dirname,'..');
const assets=path.resolve(process.argv[2] || path.join(project,'.next/static'));
const destination=path.resolve(process.argv[3] || path.join(project,'public/api/sdk/turboism-fonts.css'));
try { await access(path.dirname(destination)); } catch { process.exit(0); }
let css='';
async function collect(directory){for(const entry of await readdir(directory,{withFileTypes:true})){const file=path.join(directory,entry.name);if(entry.isDirectory())await collect(file);else if(entry.name.endsWith('.css'))css+='\n'+await readFile(file,'utf8');}}
await collect(assets);
const faces=[...new Set(css.match(/@font-face\s*\{[^{}]*\}/g)||[])];
if(!faces.length)throw new Error('No self-hosted font faces were generated by next/font');
const variables=['--font-sans','--font-mono','--font-violet-latin','--font-violet-zh','--font-violet-ja'];
const families=['geist','geistmono','tinos','notoserifsc','notoserifjp'];
const declarations=variables.map((name,index)=>{const candidates=[...css.matchAll(new RegExp(name+':\\s*([^;}]+)','g'))];const match=candidates.find(value=>value[1].replace(/[^a-z]/gi,'').toLowerCase().includes(families[index]));if(!match)throw new Error(`Missing actual webfont variable ${name}`);return `${name}:${match[1]}`;});
const result=faces.join('\n').replace(/url\((['"]?)(?:\.\.\/)+media\//g,'url($1/docs/_next/static/media/');
await writeFile(destination,`${result}\n:root{${declarations.join(';')}}\n`);
console.log(`Shared ${faces.length} self-hosted font subsets with static SDK reference.`);
